declarations.type:
∀ {ξ : ℝ} {five_le : LE.le.{0} 5 ξ}
  {lower : ∀ (x : ℝ), LE.le.{0} ξ x → LE.le.{0} (HMul.hMul.{0, 0, 0} (2 / 3) x) (Chebyshev.theta x)}
  {upper : ∀ (x : ℝ), LE.le.{0} ξ x → LE.le.{0} (Chebyshev.theta x) (HMul.hMul.{0, 0, 0} 2 x)} {ξ_1 : ℝ}
  {five_le_1 : LE.le.{0} 5 ξ_1}
  {lower_1 : ∀ (x : ℝ), LE.le.{0} ξ_1 x → LE.le.{0} (HMul.hMul.{0, 0, 0} (2 / 3) x) (Chebyshev.theta x)}
  {upper_1 : ∀ (x : ℝ), LE.le.{0} ξ_1 x → LE.le.{0} (Chebyshev.theta x) (HMul.hMul.{0, 0, 0} 2 x)},
  Eq.{1} { ξ := ξ, five_le := five_le, lower := lower, upper := upper }
      { ξ := ξ_1, five_le := five_le_1, lower := lower_1, upper := upper_1 } →
    Eq.{1} ξ ξ_1

telescope.result:
Eq.{1}
  (Eq.{1} { ξ := ξ✝, five_le := five_le✝, lower := lower✝, upper := upper✝ }
    { ξ := ξ, five_le := five_le, lower := lower, upper := upper })
  (Eq.{1} ξ✝ ξ)

declarations.type:
∀ {ι : Type w} {bad : Finset.{w} ι} {p hv f : ι → ℕ} {deg : ℕ} {one_le_deg : LE.le.{0} 1 deg}
  {p_prime : ∀ (v : ι), Membership.mem.{w, w} bad v → Nat.Prime (p v)}
  {one_le_hv : ∀ (v : ι), Membership.mem.{w, w} bad v → LE.le.{0} 1 (hv v)}
  {one_le_f : ∀ (v : ι), Membership.mem.{w, w} bad v → LE.le.{0} 1 (f v)}
  {sum_f_le : ∀ (q : ℕ), LE.le.{0} (∑ v ∈ bad with Eq.{1} (p v) q, f v) deg} {ι_1 : Type w} {bad_1 : Finset.{w} ι_1}
  {p_1 hv_1 f_1 : ι_1 → ℕ} {deg_1 : ℕ} {one_le_deg_1 : LE.le.{0} 1 deg_1}
  {p_prime_1 : ∀ (v : ι_1), Membership.mem.{w, w} bad_1 v → Nat.Prime (p_1 v)}
  {one_le_hv_1 : ∀ (v : ι_1), Membership.mem.{w, w} bad_1 v → LE.le.{0} 1 (hv_1 v)}
  {one_le_f_1 : ∀ (v : ι_1), Membership.mem.{w, w} bad_1 v → LE.le.{0} 1 (f_1 v)}
  {sum_f_le_1 : ∀ (q : ℕ), LE.le.{0} (∑ v ∈ bad_1 with Eq.{1} (p_1 v) q, f_1 v) deg_1},
  Eq.{w + 2}
      (AbcAdaptation.Reference.Iut.LocalHeightData.mk.{w} ι bad p hv f deg one_le_deg p_prime one_le_hv one_le_f
        sum_f_le)
      (AbcAdaptation.Reference.Iut.LocalHeightData.mk.{w} ι_1 bad_1 p_1 hv_1 f_1 deg_1 one_le_deg_1 p_prime_1
        one_le_hv_1 one_le_f_1 sum_f_le_1) →
    Eq.{w + 2} ι ι_1 ∧
      HEq.{w + 1} bad bad_1 ∧ HEq.{w + 1} p p_1 ∧ HEq.{w + 1} hv hv_1 ∧ HEq.{w + 1} f f_1 ∧ Eq.{1} deg deg_1

telescope.result:
Eq.{1}
  (SizeOf.sizeOf.{w + 2}
    (AbcAdaptation.Reference.Iut.LocalHeightData.mk.{w} ι bad p hv f deg one_le_deg p_prime one_le_hv one_le_f
      sum_f_le))
  (HAdd.hAdd.{0, 0, 0}
    (HAdd.hAdd.{0, 0, 0}
      (HAdd.hAdd.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 (SizeOf.sizeOf.{w + 2} ι)) (SizeOf.sizeOf.{w + 1} bad))
      (SizeOf.sizeOf.{1} deg))
    (SizeOf.sizeOf.{0} one_le_deg))
